module firr18_v5 (
    input  wire        clk,
    input  wire        rst_n,
    input  wire [7:0]  x,
    output reg  [15:0] y
);
    reg  [7:0]  xs [0:17];
    integer     i;
    reg  [23:0] acc;
    always @(*) acc = 8'd1 * xs[0] + 8'd3 * xs[1] + 8'd7 * xs[2] + 8'd13 * xs[3] + 8'd21 * xs[4] + 8'd31 * xs[5] + 8'd43 * xs[6] + 8'd57 * xs[7] + 8'd73 * xs[8] + 8'd91 * xs[9] + 8'd111 * xs[10] + 8'd133 * xs[11] + 8'd157 * xs[12] + 8'd183 * xs[13] + 8'd211 * xs[14] + 8'd241 * xs[15] + 8'd273 * xs[16] + 8'd307 * xs[17] + 24'd0;
    always @(posedge clk) begin
        if (!rst_n) begin
            for (i = 0; i < 18; i = i + 1) xs[i] <= 8'd0;
            y <= 16'd0;
        end else begin
            xs[0] <= x;
            for (i = 1; i < 18; i = i + 1) xs[i] <= xs[i-1];
            y <= acc[15:0];
        end
    end
endmodule

